terraform.code:
resource "databricks_directory" "d" {
  path = "/Shared/course"
}
resource "databricks_repo" "r" {
  url  = "https://github.com/user/demo.git"
  path = "/Repos/me@example.com/demo"
}

resource "databricks_catalog" "c" { name = "course" }
resource "databricks_schema" "s" {
  catalog_name = databricks_catalog.c.name
  name         = "bronze"
}
resource "databricks_grants" "g" {
  schema = databricks_schema.s.id
  grant {
    principal  = "students"
    privileges = ["USE_SCHEMA", "SELECT"]
  }
}

resource "databricks_job" "j" {
  name = "daily"
  task {
    task_key = "a"
    notebook_task {
      notebook_path = "/Shared/course/etl"
    }
  }
}
resource "databricks_pipeline" "p" {
  name    = "ldp"
  catalog = "course"
  schema  = "bronze"
  library {
    notebook { path = "/Shared/course/ldp" }
  }
}

resource "databricks_cluster" "c" {
  cluster_name            = "shared"
  spark_version           = data.databricks_spark_version.latest_lts.id
  node_type_id            = data.databricks_node_type.smallest.id
  autotermination_minutes = 20
  num_workers             = 1
}
resource "databricks_environments_workspace_base_environment" "e" {
  display_name = "course-env"
  filepath     = "/Volumes/course/bronze/raw/environment.yaml"
}

resource "databricks_domain" "finance" {
  tag_key  = "finance"
  subtitle = "Financial data assets"
}

resource "databricks_dashboard" "d" {
  display_name         = "Course KPIs"
  warehouse_id         = databricks_sql_endpoint.this.id
  parent_path          = "/Shared/course"
  serialized_dashboard = file("kpi.lvdash.json")
}

resource "databricks_genie_agent" "g" {
  display_name = "Sales Agent"
  warehouse_id = "abcd1234567890ef"
  parent_path  = "/Users/me@example.com/genie"
  definition = {
    data_sources = {
      tables = [{ identifier = "main.sales.orders" }]
    }
  }
}

resource "databricks_alert_v2" "a" {
  display_name = "High errors"
  query_text   = "SELECT count(*) AS n FROM logs"
  warehouse_id = "<wh-id>"
  parent_path  = "/Users/me@example.com"
  evaluation = {
    source              = { name = "n", display = "n", aggregation = "COUNT" }
    comparison_operator = "GREATER_THAN"
    threshold           = { value = { double_value = 100 } }
  }
  schedule = { quartz_cron_schedule = "0 0/15 * * * ?", timezone_id = "UTC", pause_status = "UNPAUSED" }
}

resource "databricks_query" "q" {
  warehouse_id = databricks_sql_endpoint.this.id
  display_name = "My query"
  query_text   = "SELECT 42 AS value"
  parent_path  = "/Shared/Queries"
}

resource "databricks_query" "q" {
  warehouse_id = databricks_sql_endpoint.this.id
  display_name = "My query"
  query_text   = "SELECT 42 AS value"
  parent_path  = "/Shared/Queries"
}

resource "databricks_sql_endpoint" "this" {
  name             = "wh-demo"
  cluster_size     = "2X-Small"
  max_num_clusters = 1
}

resource "databricks_connection" "mysql" {
  name            = "mysql_connection"
  connection_type = "MYSQL"
  options = {
    host     = "db.example.com"
    port     = "3306"
    user     = "user"
    password = var.pw
  }
}

resource "databricks_knowledge_assistant" "ka" {
  display_name = "course-qa"
  description  = "Answers questions about the course."
}
resource "databricks_supervisor_agent" "sa" {
  display_name = "course-supervisor"
}

resource "databricks_ai_gateway_model_service" "m" {
  parent           = "schemas/main.default"
  model_service_id = "support"
  config = {
    routing = { destinations = [{
      name                 = "primary"
      destination_type     = "DESTINATION_TYPE_PAY_PER_TOKEN_FOUNDATION_MODEL"
      pay_per_token_config = { model = "models/system.ai.databricks-gpt-5" }
      traffic_percentage   = 100
    }] }
  }
}

resource "databricks_mlflow_experiment" "e" {
  name = "/Users/me@example.com/course-exp"
}

resource "databricks_online_table" "t" {
  name = "main.default.online_table"
  spec {
    source_table_full_name = "main.default.source_table"
    primary_key_columns    = ["id"]
    run_triggered {}
  }
}
resource "databricks_online_store" "s" {
  name     = "course-store"
  capacity = "CU_1"
}

resource "databricks_registered_model" "m" {
  name         = "my_model"
  catalog_name = "main"
  schema_name  = "default"
}

resource "databricks_model_serving" "m" {
  name = "my-endpoint"
  config {
    served_entities {
      name                  = "m1"
      entity_name           = "main.default.my_model"
      entity_version        = "1"
      workload_size         = "Small"
      scale_to_zero_enabled = true
    }
  }
}

resource "databricks_user" "me" {
  user_name = "me@example.com"
}
resource "databricks_group" "g" {
  display_name = "students"
}

resource "databricks_entitlements" "e" {
  user_id              = databricks_user.me.id
  allow_cluster_create = true
}

resource "databricks_secret_scope" "s" {
  name = "app"
}
resource "databricks_secret" "k" {
  scope        = databricks_secret_scope.s.name
  key          = "api_key"
  string_value = var.api_key
}

resource "databricks_budget_policy" "p" {
  policy_name = "team-a"
  custom_tags = [{
    key   = "team"
    value = "a"
  }]
}

resource "databricks_git_credential" "g" {
  git_username          = "myuser"
  git_provider          = "gitHub"
  personal_access_token = var.gh_pat
}

resource "databricks_workspace_conf" "this" {
  custom_config = {
    "enableIpAccessLists" = true
  }
}

resource "databricks_token" "pat" {
  comment          = "Terraform"
  lifetime_seconds = 8640000
}

resource "databricks_metastore" "this" {
  name         = "primary"
  storage_root = "s3://bucket/metastore"
  region       = "us-east-1"
}
resource "databricks_metastore_assignment" "a" {
  metastore_id = databricks_metastore.this.id
  workspace_id = 123456789
}

resource "databricks_budget" "this" {
  display_name = "workspace-budget"
  alert_configurations {
    time_period        = "MONTH"
    trigger_type       = "CUMULATIVE_SPENDING_EXCEEDED"
    quantity_type      = "LIST_PRICE_DOLLARS_USD"
    quantity_threshold = "840"
    action_configurations {
      action_type = "EMAIL_NOTIFICATION"
      target      = "abc@example.com"
    }
  }
}

resource "databricks_tag_policy" "t" {
  tag_key     = "cost_center"
  description = "Cost center"
  values = [{ name = "a" }, { name = "b" }]
}

resource "databricks_mws_workspaces" "w" {
  account_id     = var.account_id
  workspace_name = "serverless-workspace"
  aws_region     = "us-east-1"
  compute_mode   = "SERVERLESS"
}

resource "databricks_user" "me" {
  user_name = "me@example.com"
}
resource "databricks_mws_permission_assignment" "a" {
  workspace_id = databricks_mws_workspaces.w.workspace_id
  principal_id = databricks_user.me.id
  permissions  = ["USER"]
}

resource "databricks_account_federation_policy" "p" {
  policy_id = "my-policy"
  oidc_policy = {
    issuer        = "https://myidp.example.com"
    subject_claim = "sub"
  }
}

resource "databricks_mws_credentials" "c" {
  credentials_name = "creds"
  role_arn         = aws_iam_role.cross_account.arn
}
resource "databricks_mws_storage_configurations" "s" {
  account_id                 = var.account_id
  storage_configuration_name = "storage"
  bucket_name                = aws_s3_bucket.root.bucket
}

resource "databricks_account_setting_v2" "s" {
  name = "llm_proxy_partner_powered"
  boolean_val = {
    value = false
  }
}
